 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid colored edge is the stop-wall; objects fall toward it.
    if all(v != 0 for v in grid[0]):
        dr = 1
        wall = set((0, c) for c in range(w))
    elif all(v != 0 for v in grid[-1]):
        dr = -1
        wall = set((h - 1, c) for c in range(w))
    else:
        raise ValueError('No solid horizontal wall')

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in wall or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color and (nr,nc) not in wall:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            objects.append({'color': color, 'cells': cells})

    # Move each rigid monochrome object one cell at a time until blocked.
    while True:
        occupied = {p for obj in objects for p in obj['cells']}
        moving = []
        for i, obj in enumerate(objects):
            own = set(obj['cells'])
            destinations = [(r + dr, c) for r, c in obj['cells']]
            if all(0 <= r < h and 0 <= c < w and (r,c) not in wall and ((r,c) not in occupied or (r,c) in own) for r,c in destinations):
                moving.append(i)
        if not moving:
            break
        for i in moving:
            objects[i]['cells'] = [(r + dr, c) for r,c in objects[i]['cells']]

    out = [row[:] for row in grid]
    for obj in objects:
        for r,c in obj['cells']:
            out[r][c] = 0
    for obj in objects:
        for r,c in obj['cells']:
            out[r][c] = obj['color']
    return out
